import{_ as o,o as a,c as l,ak as i,j as c}from"./chunks/framework.gO8r5hi3.js";const m=JSON.parse('{"title":"Projet en classe : Tappy","description":"","frontmatter":{},"headers":[],"relativePath":"09_a_12_Projet_en_classe_Tappy.md","filePath":"09_a_12_Projet_en_classe_Tappy.md","lastUpdated":1772142321000}'),r={name:"09_a_12_Projet_en_classe_Tappy.md"};function n(d,e,t,s,u,p){return a(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="projet-en-classe-tappy" tabindex="-1">Projet en classe : Tappy <a class="header-anchor" href="#projet-en-classe-tappy" aria-label="Permalink to “Projet en classe : Tappy”">​</a></h1><p>Dans les prochains cours (09 à 12), nous allons réaliser un jeu de type &quot;endless runner&quot; où le joueur contrôle un avion qui doit éviter les obstacles et collecter des étoiles pour marquer des points.</p><h2 id="cours-09-deplacer-le-decor" tabindex="-1">Cours 09 - Déplacer le décor <a class="header-anchor" href="#cours-09-deplacer-le-decor" aria-label="Permalink to “Cours 09 - Déplacer le décor”">​</a></h2><h3 id="_1-revision-des-deplacement" tabindex="-1">1. Révision des déplacement <a class="header-anchor" href="#_1-revision-des-deplacement" aria-label="Permalink to “1. Révision des déplacement”">​</a></h3><h4 id="dans-le-script-deplacementdecor" tabindex="-1">Dans le script <code>DéplacementDecor</code>: <a class="header-anchor" href="#dans-le-script-deplacementdecor" aria-label="Permalink to “Dans le script DéplacementDecor:”">​</a></h4><ul><li><p>Créer une variable de type <code>float</code> nommée <code>vitesse</code> et lui assigner une valeur de <code>1f</code>.</p></li><li><p>Créer une variable de type <code>int</code> nommée <code>direction</code> et lui assigner une valeur de <code>1</code>.</p></li><li><p>Créer une variable de type <code>float</code> nommée <code>limiteGauche</code> et lui assigner une valeur de <code>0f</code>.</p></li><li><p>Créer une variable de type <code>float</code> nommée <code>limiteDroite</code> et lui assigner une valeur de <code>10f</code>.</p></li><li><p>Dans la méthode <code>Update()</code>, ajouter le code déplacer le décor:</p><ul><li>Utilise la fonction <code>Translate()</code> pour déplacer le décor horizontalement en fonction de la <code>vitesse</code> et de la <code>direction</code>.</li><li>Gardez la position y du décor constante: ex: <code>transform.Translate(vitesse * direction * Time.deltaTime, 0, 0);</code></li><li>Si la direction est négative et que la position x du décor est inférieure ou égale à <code>limiteGauche</code>, replacer le décor à la <code>limiteDroite</code>.</li><li>Si la direction est positive et que la position x du décor est supérieure ou égale à <code>limiteDroite</code>, replacer le décor à la <code>limiteGauche</code>.</li></ul></li></ul><h4 id="dans-l-inspecteur-de-unity" tabindex="-1">Dans l&#39;inspecteur de Unity <a class="header-anchor" href="#dans-l-inspecteur-de-unity" aria-label="Permalink to “Dans l&#39;inspecteur de Unity”">​</a></h4><ul><li>Pour le fond, mettre une <code>vitesse</code> de <code>1f</code>, une <code>direction</code> de <code>-1</code>, une <code>limiteGauche</code> de <code>-16.83</code> et une <code>limiteDroite</code> de <code>16.83</code>.</li><li>Pour le bloc de nuages, mettre une <code>vitesse</code> de <code>2f</code>, une <code>direction</code> de <code>-1</code>, une <code>limiteGauche</code> de <code>-20.5</code> et une <code>limiteDroite</code> de <code>11.72</code>.</li></ul><h3 id="_2-ajouter-les-collisions" tabindex="-1">2. Ajouter les collisions <a class="header-anchor" href="#_2-ajouter-les-collisions" aria-label="Permalink to “2. Ajouter les collisions”">​</a></h3><ul><li>Sur tous les éléments du décor, ajouter un composant <code>PolygonCollider2D</code> .</li><li>Sur l&#39;avion, ajouter un composant <code>BoxCollider2D</code>.</li><li>Sur les étoiles, ajouter un composant <code>BoxCollider2D</code> et cocher la case <code>Is Trigger</code>.</li></ul><h3 id="_3-ajouter-un-rigidbody2d-sur-l-avion" tabindex="-1">3. Ajouter un rigidbody2d sur l&#39;avion <a class="header-anchor" href="#_3-ajouter-un-rigidbody2d-sur-l-avion" aria-label="Permalink to “3. Ajouter un rigidbody2d sur l&#39;avion”">​</a></h3><ul><li>Mettez les paramètres du <code>Rigidbody2D</code> de l&#39;avion comme suit: <ul><li><code>Mass</code>: 1</li><li><code>Linear Damping</code>: 1.2</li><li><code>Angular Damping</code>: 1</li><li><code>Gravity Scale</code>: 1</li><li>Constraints: Cocher <code>Freeze Rotation</code></li></ul></li></ul><h2 id="cours-10-deplacer-l-avion-et-gerer-les-collisions" tabindex="-1">Cours 10 - Déplacer l&#39;avion et gérer les collisions <a class="header-anchor" href="#cours-10-deplacer-l-avion-et-gerer-les-collisions" aria-label="Permalink to “Cours 10 - Déplacer l&#39;avion et gérer les collisions”">​</a></h2><h3 id="_4-deplacer-l-avion" tabindex="-1">4. Déplacer l&#39;avion <a class="header-anchor" href="#_4-deplacer-l-avion" aria-label="Permalink to “4. Déplacer l&#39;avion”">​</a></h3><h4 id="dans-le-script-deplacementavion" tabindex="-1">Dans le script <code>DeplacementAvion</code>: <a class="header-anchor" href="#dans-le-script-deplacementavion" aria-label="Permalink to “Dans le script DeplacementAvion:”">​</a></h4><ul><li><p>Ajouter une variable publique de type <code>Rigidbody2D</code> nommée <code>rigid</code>.</p></li><li><p>Ajouter une variable publique de type <code>float</code> nommée <code>vitesse</code> et lui assigner une valeur de <code>0.2f</code>.</p></li><li><p>Ajouter une variable de type <code>float</code> nommée <code>deplacementHorizontal</code>.</p></li><li><p>Ajouter une variable de type <code>float</code> nommée <code>deplacementVertical</code>.</p></li><li><p>Ajouter une variable de type <code>bool</code> nommée <code>estMort</code> et lui assigner une valeur de <code>false</code>.</p></li><li><p>Dans la méthode <code>Start()</code>, assigner le composant <code>Rigidbody2D</code> de l&#39;avion à la variable <code>rigid</code> en utilisant <code>GetComponent&lt;Rigidbody2D&gt;()</code>.</p></li><li><p>Dans la méthode <code>Update()</code>, modifier la vélocité linéaire du <code>Rigidbody2D</code> de l&#39;avion: <code>rigid.linearVelocity += new Vector2(deplacementHorizontal * vitesse, deplacementVertical * vitesse);</code></p></li></ul><h3 id="_5-gerer-les-collisions-avec-le-decor" tabindex="-1">5. Gérer les collisions avec le décor <a class="header-anchor" href="#_5-gerer-les-collisions-avec-le-decor" aria-label="Permalink to “5. Gérer les collisions avec le décor”">​</a></h3><h4 id="dans-le-script-deplacementavion-1" tabindex="-1">Dans le script <code>DeplacementAvion</code>: <a class="header-anchor" href="#dans-le-script-deplacementavion-1" aria-label="Permalink to “Dans le script DeplacementAvion:”">​</a></h4><ul><li>Ajouter une méthode <code>OnCollisionEnter2D(Collision2D collision)</code>. <ul><li>Dans cette méthode, si l&#39;élément touché possède le tag &quot;Decor&quot; et que <code>estMort</code> est <code>false</code>, alors: <ul><li>Assigner <code>true</code> à la variable <code>estMort</code>.</li><li>Retirer la contrainte de rotation du <code>Rigidbody2D</code> de l&#39;avion pour permettre à l&#39;avion de tourner librement.</li><li>Appliquer une vélocité de rotation à l&#39;avion pour simuler une chute en spirale. Par exemple: <code>rb.angularVelocity = 100f;</code></li></ul></li></ul></li></ul><h3 id="_6-gerer-les-collisions-avec-les-etoiles" tabindex="-1">6. Gérer les collisions avec les étoiles <a class="header-anchor" href="#_6-gerer-les-collisions-avec-les-etoiles" aria-label="Permalink to “6. Gérer les collisions avec les étoiles”">​</a></h3><h4 id="dans-le-script-deplacementavion-2" tabindex="-1">Dans le script <code>DeplacementAvion</code>: <a class="header-anchor" href="#dans-le-script-deplacementavion-2" aria-label="Permalink to “Dans le script DeplacementAvion:”">​</a></h4><ul><li>Ajouter une méthode <code>OnTriggerEnter2D(Collider2D collision)</code>. <ul><li>Dans cette méthode, si l&#39;élément touché possède le tag &quot;Etoile&quot;, alors: <ul><li>Accéder au script <code>GestionEtoile</code> de l&#39;étoile touchée en utilisant <code>collision.GetComponent&lt;GestionEtoile&gt;()</code>.</li><li>Appeler la méthode publique <code>Cacher</code> du script <code>GestionEtoile</code></li></ul></li></ul></li></ul><h2 id="cours-11-ajouter-du-son" tabindex="-1">Cours 11 - Ajouter du son <a class="header-anchor" href="#cours-11-ajouter-du-son" aria-label="Permalink to “Cours 11 - Ajouter du son”">​</a></h2><h3 id="_7-gestion-du-son" tabindex="-1">7. Gestion du son <a class="header-anchor" href="#_7-gestion-du-son" aria-label="Permalink to “7. Gestion du son”">​</a></h3><p>Sur l&#39;objet de l&#39;avion, ajouter un composant <code>AudioSource</code> et assigner le son de la musique et faire jouer la musique au démarrage du jeu et en boucle.</p><h4 id="dans-le-script-deplacementavion-3" tabindex="-1">Dans le script <code>DeplacementAvion</code>: <a class="header-anchor" href="#dans-le-script-deplacementavion-3" aria-label="Permalink to “Dans le script DeplacementAvion:”">​</a></h4><ul><li>Créer deux variables de type <code>AudioClip</code> pour stocker les sons de la collision et de la collection d&#39;étoiles et les assigner dans l&#39;inspecteur.</li><li>Enregistrer la référence du composant <code>AudioSource</code> de l&#39;avion dans une variable.</li></ul><h4 id="dans-la-fonction-oncollisionenter2d-du-script-deplacementavion" tabindex="-1">Dans la fonction <code>OnCollisionEnter2D</code> du script <code>DeplacementAvion</code>: <a class="header-anchor" href="#dans-la-fonction-oncollisionenter2d-du-script-deplacementavion" aria-label="Permalink to “Dans la fonction OnCollisionEnter2D du script DeplacementAvion:”">​</a></h4><ul><li>Ajouter une ligne de code pour jouer le son de la collision lorsque l&#39;avion touche le décor. Par exemple: <code>audioSource.PlayOneShot(sonCollision);</code></li></ul><h4 id="dans-la-fonction-ontriggerenter2d-du-script-deplacementavion" tabindex="-1">Dans la fonction <code>OnTriggerEnter2D</code> du script <code>DeplacementAvion</code>: <a class="header-anchor" href="#dans-la-fonction-ontriggerenter2d-du-script-deplacementavion" aria-label="Permalink to “Dans la fonction OnTriggerEnter2D du script DeplacementAvion:”">​</a></h4><ul><li>Ajouter une ligne de code pour jouer le son de la collection d&#39;étoiles lorsque l&#39;avion touche une étoile. Par exemple: <code>audioSource.PlayOneShot(sonEtoile);</code></li></ul><h2 id="cours-12-afficher-le-pointage" tabindex="-1">Cours 12 - Afficher le pointage <a class="header-anchor" href="#cours-12-afficher-le-pointage" aria-label="Permalink to “Cours 12 - Afficher le pointage”">​</a></h2><h3 id="_8-creer-un-canvas-pour-afficher-le-pointage" tabindex="-1">8. Créer un canvas pour afficher le pointage <a class="header-anchor" href="#_8-creer-un-canvas-pour-afficher-le-pointage" aria-label="Permalink to “8. Créer un canvas pour afficher le pointage”">​</a></h3><ul><li>Dans Unity, créer un objet <code>Canvas</code> et le nommer &quot;CanvasPointage&quot;. Assurez-vous que le&quot;Scale Mode&quot; du <code>Canvas</code> est réglé sur &quot;Scale With Screen Size&quot; pour que le pointage s&#39;adapte à différentes résolutions d&#39;écran.</li><li>Dans le <code>CanvasPointage</code>, créer un objet <code>TMPText</code> et le nommer &quot;TextPointage&quot;.</li><li>Positionner le <code>TextPointage</code> en haut à gauche de l&#39;écran et ajuster sa taille et sa police pour qu&#39;il soit bien visible.</li></ul><h4 id="dans-le-script-deplacementavion-4" tabindex="-1">Dans le script <code>DeplacementAvion</code>: <a class="header-anchor" href="#dans-le-script-deplacementavion-4" aria-label="Permalink to “Dans le script DeplacementAvion:”">​</a></h4><ul><li>Ajouter une variable publique de type <code>TMP_Text</code> nommée <code>textPointage</code> et l&#39;assigner dans l&#39;inspecteur en faisant glisser le <code>TextPointage</code> du <code>CanvasPointage</code>.</li><li>Ajouter une variable de type <code>int</code> nommée <code>pointage</code> et lui assigner une valeur de <code>0</code>.</li><li>Dans la fonction <code>OnTriggerEnter2D</code>, après jouer le son de la collection d&#39;étoiles, augmenter le pointage de 1 et mettre à jour le texte affiché dans <code>textPointage</code>.</li><li>Utiliser l&#39;interpolation de chaîne pour afficher le pointage: <code>textPointage.text = $&quot;Pointage: {pointage}&quot;;</code></li></ul><h2 id="video-complet" tabindex="-1">Vidéo complet <a class="header-anchor" href="#video-complet" aria-label="Permalink to “Vidéo complet”">​</a></h2>',37),c("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/xuViPNhIjzc?si=ZTGbWuBfKqtHYJWC",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",referrerpolicy:"strict-origin-when-cross-origin",allowfullscreen:""},null,-1)])])}const v=o(r,[["render",n]]);export{m as __pageData,v as default};
